const allowedTopics = [
  'Billing & Payment',
  'Product Issue',
  'Delivery & Shipping',
  'Order Management',
  'Account & Login',
  'Store & Service',
  'Other',
];

const responseText = $json.candidates?.[0]?.content?.parts
  ?.map((part) => part.text || '')
  .join('') || '';

let result;
try {
  result = JSON.parse(responseText);
} catch {
  result = {
    topic: 'Other',
    confidence: 0,
    reason: 'The model response was not valid JSON.',
  };
}

if (!allowedTopics.includes(result.topic)) {
  result.topic = 'Other';
}

return [{
  json: {
    ticketText: $items('Set Ticket Text')[0].json.ticketText,
    topic: result.topic,
    confidence: Number(result.confidence) || 0,
    reason: result.reason || '',
  },
}];
